#define CHECK(x) do{auto e=(x);if(e!=cudaSuccess){printf("CUDA ERROR %s\n",cudaGetErrorString(e));return 2;}}while(0)
int main(){float data[]={2.5f,-3.5f},pixels[]={1,2,3,4,5,6,7,8},expected[]={3,-30,-27,7.5f,2,4.5f},result[6],*input,*output;CHECK(cudaMalloc(&input,sizeof(data)));CHECK(cudaMalloc(&output,sizeof(result)));CHECK(cudaMemcpy(input,data,sizeof(data),cudaMemcpyHostToDevice));cudaArray_t array;auto channel=cudaCreateChannelDesc<float>();CHECK(cudaMallocArray(&array,&channel,4,2));CHECK(cudaMemcpy2DToArray(array,0,0,pixels,16,16,2,cudaMemcpyHostToDevice));cudaResourceDesc resource={};resource.resType=cudaResourceTypeArray;resource.res.array.array=array;cudaTextureDesc desc={};desc.filterMode=cudaFilterModeLinear;desc.addressMode[0]=desc.addressMode[1]=cudaAddressModeClamp;desc.readMode=cudaReadModeElementType;cudaTextureObject_t tex;CHECK(cudaCreateTextureObject(&tex,&resource,&desc,nullptr));multipleTypes<<<1,1>>>(input,output,tex);CHECK(cudaGetLastError());CHECK(cudaDeviceSynchronize());CHECK(cudaMemcpy(result,output,sizeof(result),cudaMemcpyDeviceToHost));for(int i=0;i<6;i++)if(result[i]!=expected[i]){printf("FAIL component=%d actual=%g expected=%g\n",i,result[i],expected[i]);return 1;}CHECK(cudaDestroyTextureObject(tex));CHECK(cudaFreeArray(array));CHECK(cudaFree(input));CHECK(cudaFree(output));printf("PASS native multiple helper types: 3, -30, -27, 7.5, 2, 4.5; four type parameters, reversed nested arguments, explicit specialization and texture helpers\n");return 0;}
